# Керосиновая лампа «летучая мышь»: все детали по размерам (метры, ось Z вверх, стол на z = 0)
import math, numpy as np
from mathutils import Matrix, Vector
from geo import cr, fil, offset, shell, lathe, sweep, circle, rrect, Group

def build():
    lamp, glass, table, flame = Group("Lamp"), Group("Glass"), Group("Table"), Group("Flame")
    P, B, W, K = "paint", "brass", "wire", "wick"
    pol = lambda rho, ang, z: (rho * math.cos(math.radians(ang)), rho * math.sin(math.radians(ang)), z)

    # --- бак ---
    tank = fil([(0, 0.0065, 0), (0.056, 0.0065, 0.004), (0.062, 0.0015, 0.003), (0.068, 0.0, 0.002), (0.0745, 0.0015, 0.003), (0.078, 0.0085, 0.004),
                (0.078, 0.0165, 0.001), (0.0806, 0.0195, 0.002), (0.078, 0.0225, 0.001), (0.078, 0.0405, 0.001), (0.0806, 0.0435, 0.002), (0.078, 0.0465, 0.001),
                (0.078, 0.0525, 0.001), (0.0798, 0.0548, 0.0015), (0.0775, 0.0572, 0.001), (0.071, 0.0615, 0.02), (0.052, 0.0695, 0.03), (0.036, 0.0728, 0.006),
                (0.0315, 0.0735, 0.0015), (0.0315, 0.0795, 0.001), (0.0295, 0.0805, 0.0008), (0.0275, 0.0800, 0.0008), (0.0275, 0.074, 0)], n=3)
    lamp.grid(lathe(tank, 80), P)
    # --- горелка (латунь) и фитиль ---
    lamp.grid(lathe(fil([(0.0272, 0.0800, 0), (0.0305, 0.0812, 0.0008), (0.0305, 0.0842, 0.001), (0.026, 0.0875, 0.003), (0.0165, 0.1035, 0.004), (0.0135, 0.1085, 0.003), (0.0085, 0.1108, 0.002), (0.0, 0.1112, 0)]), 64), B)
    lamp.grid(sweep([(0, 0, 0.1095), (0, 0, 0.1150)], 1, section=rrect(0.0022, 0.011, 0.0005, 1), up=(1, 0, 0)), K)
    # --- тарелка под стекло ---
    lamp.grid(lathe(fil([(0.0312, 0.0862, 0.0003), (0.0470, 0.0862, 0.001), (0.0505, 0.0872, 0.001), (0.0518, 0.0912, 0.0004), (0.0508, 0.0914, 0.0004), (0.0492, 0.0885, 0.001), (0.0465, 0.0880, 0.001), (0.0312, 0.0880, 0.0003)], n=3), 72), P, loop=True)
    # --- стекло ---
    go = cr([(0.0375, 0.0888), (0.0392, 0.0935), (0.0455, 0.1060), (0.0520, 0.1220), (0.0550, 0.1400), (0.0520, 0.1580), (0.0440, 0.1750), (0.0360, 0.1890), (0.0322, 0.1975), (0.0318, 0.2030)], 4)
    glass.grid(lathe(shell(go, 0.0022), 72), "glass", loop=True, hmax=1)
    # --- верх: колпак, камера, труба, зонт ---
    lamp.grid(lathe(shell(fil([(0.0372, 0.1985, 0), (0.0378, 0.2045, 0.002), (0.0335, 0.2100, 0.004), (0.0262, 0.2190, 0.006), (0.0240, 0.2235, 0.003), (0.0240, 0.2475, 0.0008), (0.0252, 0.2485, 0.0005), (0.0252, 0.2500, 0)], n=4), 0.0012), 72), P, loop=True)
    lamp.grid(lathe(fil([(0.0240, 0.2262, 0), (0.0290, 0.2262, 0.002), (0.0305, 0.2285, 0.002), (0.0305, 0.2410, 0.002), (0.0290, 0.2432, 0.002), (0.0240, 0.2432, 0)]), 72), P)
    lamp.grid(lathe(fil([(0, 0.2560, 0), (0.020, 0.2552, 0.01), (0.034, 0.2512, 0.006), (0.0380, 0.2484, 0.002), (0.0398, 0.2478, 0.0008), (0.0407, 0.2490, 0.0008), (0.0398, 0.2514, 0.002), (0.035, 0.2562, 0.008), (0.021, 0.2608, 0.012), (0.0075, 0.2624, 0.004), (0.0058, 0.2632, 0.0008), (0.0052, 0.2652, 0.001), (0.003, 0.2664, 0.001), (0, 0.2666, 0)], n=4), 72), P)
    for a in (30, 150, 270): lamp.grid(sweep([pol(0.0235, a, 0.2490), pol(0.0235, a, 0.2558)], 0.0024, 8, caps=False), P)
    # --- боковые трубки ---
    for sx in (1, -1):
        tube = cr([(sx * 0.019, 0, 0.2350), (sx * 0.040, 0, 0.2390), (sx * 0.056, 0, 0.2370), (sx * 0.0685, 0, 0.2270), (sx * 0.0725, 0, 0.2100), (sx * 0.0730, 0, 0.1700), (sx * 0.0730, 0, 0.1200), (sx * 0.0730, 0, 0.0800), (sx * 0.0728, 0, 0.0570)], 7)
        lamp.grid(sweep(tube, 0.0095, 20, caps=False, up=(0, 1, 0)), P)
        lamp.grid(sweep([(sx * 0.073, 0, z) for z in (0.0605, 0.0622, 0.0632, 0.0668, 0.0678, 0.0690)], [0.0096, 0.0108, 0.0113, 0.0113, 0.0108, 0.0096], 20, caps=False), P)
        lamp.grid(sweep([(sx * x, 0, 0.2371 + (x - 0.0305) * 0.19) for x in (0.0300, 0.0312, 0.0322, 0.0350, 0.0360, 0.0370)], [0.0096, 0.0106, 0.0110, 0.0110, 0.0106, 0.0096], 20, caps=False, up=(0, 1, 0)), P)
        # ушко и ось дужки
        lamp.grid(sweep([(sx * x, 0, 0.214) for x in (0.0812, 0.0822, 0.0834, 0.0840)], [0.0058, 0.0066, 0.0066, 0.0058], 16), P)
        lamp.grid(sweep([(sx * x, 0, 0.214) for x in (0.0835, 0.0925, 0.0928, 0.0940, 0.0946)], [0.0019, 0.0019, 0.0036, 0.0036, 0.0028], 12), W)
        th = np.linspace(0, 2 * math.pi, 20, endpoint=False)
        lamp.grid(sweep([(sx * 0.0890, 0.0042 * math.cos(t), 0.214 + 0.0042 * math.sin(t)) for t in th], 0.0019, 8, loop=True), W, loop=True)
        # кольцо защиты -> трубка
        lamp.grid(sweep([(sx * 0.0588, 0, 0.141), (sx * 0.0640, 0, 0.141)], 0.0016, 8), W)
    # --- дужка (наклонена назад) ---
    half = [(0.0890, 0.0042), (0.0905, 0.020), (0.0915, 0.050), (0.0850, 0.085), (0.0660, 0.118), (0.0360, 0.139), (0, 0.146)]
    a = math.radians(16); bail = cr(half + [(-x, h) for x, h in half[-2::-1]], 8)
    lamp.grid(sweep([(x, h * math.sin(a), 0.214 + h * math.cos(a)) for x, h in bail], 0.0019, 10, up=(0, 1, 0)), W, hmax=0.12)
    # --- защитная сетка стекла ---
    th = np.linspace(0, 2 * math.pi, 96, endpoint=False)
    lamp.grid(sweep([(0.0592 * math.cos(t), 0.0592 * math.sin(t), 0.141) for t in th], 0.0016, 8, loop=True), W, loop=True, hmax=0.12)
    gw = cr([(0.0500, 0.0905), (0.0535, 0.100), (0.0575, 0.118), (0.0592, 0.141), (0.0570, 0.160), (0.0500, 0.178), (0.0420, 0.192), (0.0385, 0.2005)], 6)
    for ang in (45, 135, 225, 315): lamp.grid(sweep([pol(r, ang, z) for r, z in gw], 0.0016, 8), W, hmax=0.12)
    # --- регулятор фитиля ---
    rod = [pol(r, 242, 0.0835) for r in (0.020, 0.0655)]; lamp.grid(sweep(rod, 0.0017, 8), W)
    gear = circle(56) * (1 - 0.09 * (np.sin(np.linspace(0, 2 * math.pi, 56, endpoint=False) * 14) > 0))[:, None]
    lamp.grid(sweep([pol(r, 242, 0.0835) for r in (0.0650, 0.0655, 0.0683, 0.0688)], [0.0086, 0.0095, 0.0095, 0.0086], section=gear), B)
    # --- заливная горловина с пробкой ---
    ang = 300; ax = Vector((math.sin(math.radians(22)) * math.cos(math.radians(ang)), math.sin(math.radians(22)) * math.sin(math.radians(ang)), math.cos(math.radians(22))))
    M = np.array(Matrix.Translation(pol(0.0555, ang, 0.0672)) @ Vector((0, 0, 1)).rotation_difference(ax).to_matrix().to_4x4())
    lamp.grid(lathe([(0.0098, -0.004), (0.0098, 0.0045)], 40, M), P)
    lamp.grid(lathe(fil([(0.0098, 0.0040, 0), (0.0128, 0.0040, 0.0006), (0.0128, 0.0105, 0.0012), (0.0105, 0.0122, 0.002), (0, 0.0128, 0)]), 96, M, knurl=(24, 0.07, 0.0046, 0.0100)), B)
    # --- рычаг подъёма стекла ---
    lever = cr([(0.046, 0.018, 0.0893), (0.060, 0.026, 0.0890), (0.074, 0.031, 0.0860), (0.086, 0.032, 0.0790), (0.094, 0.032, 0.0720)], 6)
    lamp.grid(sweep(lever, 0.0018, 8), W)
    d = lever[-1] - lever[-3]; d /= np.linalg.norm(d); Ml = np.array(Matrix.Translation(Vector(lever[-1] + d * 0.006)) @ Vector((0, 0, 1)).rotation_difference(Vector(np.cross(d, (0, 1, 0))).normalized()).to_matrix().to_4x4())
    lamp.grid(lathe(fil([(0, -0.0009, 0), (0.0072, -0.0009, 0.0006), (0.0072, 0.0009, 0.0006), (0, 0.0009, 0)]), 28, Ml), P)
    # --- стол: пять досок ---
    rng = np.random.default_rng(7)
    for i in range(5):
        y = (i - 2) * 0.097 + rng.uniform(-0.0006, 0.0006); L = 0.26 + rng.uniform(-0.006, 0.006); dz = rng.uniform(-0.0009, 0.0003)
        table.grid(sweep([(-L, y, -0.011 + dz), (L + rng.uniform(-0.004, 0.004), y, -0.011 + dz)], 1, section=rrect(0.022, 0.094, 0.0022, 2), up=(0, 1, 0)), "wood", hmax=0.3)
    # --- пламя ---
    fl = lathe(cr([(0, 0.1128), (0.0042, 0.1140), (0.0066, 0.1195), (0.0058, 0.1275), (0.0034, 0.1360), (0.0012, 0.1430), (0, 0.1470)], 5), 24)
    flame.grid([r * np.array([1.25, 0.5, 1]) for r in fl], "flame", hmax=1)
    return lamp, glass, table, flame
